function outputPreview(text) {
  const characters = Array.from(text);
  return {
    text: characters.slice(0, 4000).join('').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f]/g, '\uFFFD'),
    shortened: characters.length > 4000
  };
}

export async function runProjectCommand(input, api) {
  let args;
  try { args = JSON.parse(input.arguments); }
  catch { throw new Error('arguments-must-be-json-array'); }
  if (!Array.isArray(args) || args.length > 63 || args.some(value => typeof value !== 'string')) {
    throw new Error('arguments-must-be-string-array');
  }
  const request = { argv: [input.program, ...args], timeoutMs: input.timeout_ms };
  if (input.cwd !== '') request.cwd = input.cwd;
  const result = await api.commands.run(request);
  const stdout = outputPreview(result.stdout);
  const stderr = outputPreview(result.stderr);
  const success = result.exitCode === 0 && !result.timedOut;
  await api.ui.present({ view: {
    title: '项目命令结果',
    blocks: [
      { type: 'status', tone: success ? 'success' : 'warning', text: result.timedOut
        ? '命令已超时，宿主已请求停止；请核对已产生的改动。'
        : success ? '命令已结束，退出码为 0。' : '命令已结束，但没有以退出码 0 正常完成。' },
      { type: 'fields', items: [
        { label: '退出码', value: result.exitCode === null ? '未取得' : String(result.exitCode) },
        { label: '耗时', value: String(result.durationMs) + ' ms' },
        { label: '是否超时', value: result.timedOut ? '是' : '否' },
        { label: '结束信号', value: result.signal || '无' },
        { label: '标准输出字节', value: String(result.stdoutBytes) + ' B' },
        { label: '标准错误字节', value: String(result.stderrBytes) + ' B' },
        { label: '宿主截断输出', value: result.stdoutTruncated || result.stderrTruncated ? '是' : '否' },
        { label: '结果卡再次截断', value: stdout.shortened || stderr.shortened ? '是' : '否' }
      ] },
      { type: 'text', text: '标准输出（stdout）' },
      { type: 'code', language: 'text', code: stdout.text || '（无输出）' },
      { type: 'text', text: '标准错误（stderr）' },
      { type: 'code', language: 'text', code: stderr.text || '（无输出）' },
      { type: 'text', text: '每路最多展示前 4000 个 Unicode 字符，不支持的控制字符替换为 �。结果卡没有写入草稿或发送消息；已批准的本机命令本身可能修改文件或联网。' }
    ],
    actions: []
  } });
  return { exitCode: result.exitCode, timedOut: result.timedOut, durationMs: result.durationMs,
    stdoutTruncated: result.stdoutTruncated, stderrTruncated: result.stderrTruncated };
}
